//! Use code generated by a build script that ran a vendored `protoc`.
//!
//! See `build.rs` and `proto/echo.proto`.

/// Generated messages and service stubs.
pub mod proto {
    ::tonic::include_proto!("echo");
}

#[cfg(test)]
mod tests {
    use super::proto::EchoRequest;
    use super::proto::echo_client::EchoClient;
    use super::proto::echo_server::EchoServer;

    #[test]
    fn generated_types_exist() {
        let request = EchoRequest {
            text: "hi".to_owned(),
        };
        assert_eq!(request.text, "hi");
        // The client and server stubs are generated too.
        let _ = std::any::type_name::<EchoClient<tonic::transport::Channel>>();
        let _ = std::any::type_name::<EchoServer<()>>();
    }
}
